mapper.select:
SELECT COUNT(*) AS cnt
FROM information_schema.ins_stables
WHERE db_name = #{database}
  AND stable_name = #{stableName}

SELECT COUNT(*) AS cnt
FROM information_schema.ins_columns
WHERE db_name = #{database}
  AND table_name = #{tableName}
  AND col_name = #{columnName}

SELECT
    ts,event_ts,point_id,point_code,point_name,value_text,unit,quality,success,message,raw_json,processed_json,metadata_json
FROM ${database}.${subTable}
WHERE 1 = 1

    AND point_id = #{pointId}


    AND event_ts >= #{startTs}


    AND event_ts <= #{endTs}

ORDER BY event_ts DESC, ts DESC
LIMIT #{limit}

SELECT
    ts,event_ts,point_id,point_code,point_name,value_text,unit,quality,success,message,raw_json,processed_json,metadata_json
FROM ${database}.${subTable}
WHERE 1 = 1

    AND point_id = #{pointId}


    AND event_ts >= #{startTs}


    AND event_ts <= #{endTs}

ORDER BY event_ts DESC, ts DESC, point_key ASC
LIMIT #{limit}
